(function initCookieConsent(){var STORAGE_KEY='dns_cookie_consent';var EXPIRY_DAYS=365;function saveConsent(analytics){var record={necessary:true,analytics:analytics,timestamp:Date.now(),expiry:Date.now()+(EXPIRY_DAYS*24*60*60*1000)};try{localStorage.setItem(STORAGE_KEY,JSON.stringify(record));}catch(e){}}
function getConsent(){try{var raw=localStorage.getItem(STORAGE_KEY);if(!raw)return null;var record=JSON.parse(raw);if(!record||!record.expiry)return null;if(Date.now()>record.expiry){localStorage.removeItem(STORAGE_KEY);return null;}
return record;}catch(e){return null;}}
function dispatchConsentUpdate(analytics){var event=new CustomEvent('consentUpdate',{detail:{analytics:analytics}});document.dispatchEvent(event);}
function hideBanner(){var banner=document.getElementById('cookie-banner');if(banner){banner.setAttribute('hidden','');}}
function showBanner(){var banner=document.getElementById('cookie-banner');if(banner){banner.removeAttribute('hidden');var firstBtn=banner.querySelector('button');if(firstBtn)firstBtn.focus();}}
function acceptAll(){saveConsent(true);hideBanner();dispatchConsentUpdate(true);}
function rejectNonEssential(){saveConsent(false);hideBanner();dispatchConsentUpdate(false);}
function bindButtons(){var acceptBtn=document.getElementById('cookie-accept');var rejectBtn=document.getElementById('cookie-reject');if(acceptBtn)acceptBtn.addEventListener('click',acceptAll);if(rejectBtn)rejectBtn.addEventListener('click',rejectNonEssential);}
function init(){var consent=getConsent();if(consent){dispatchConsentUpdate(consent.analytics);return;}
setTimeout(function(){showBanner();bindButtons();},800);}
window.DNS=window.DNS||{};window.DNS.openCookiePreferences=function(){showBanner();bindButtons();};window.DNS.analyticsAllowed=function(){var consent=getConsent();return consent?consent.analytics:false;};if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',init);}else{init();}})();